// Simple driver: reads a wasm file and feeds it to LLVMFuzzerTestOneInput.
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size);

int
main(int argc, char *argv[])
{
    if (argc < 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 2;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "cannot open %s\n", argv[1]);
        return 2;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (len < 0) {
        fclose(f);
        return 2;
    }
    std::vector<uint8_t> data((size_t)len);
    if (len > 0 && fread(data.data(), 1, (size_t)len, f) != (size_t)len) {
        fprintf(stderr, "read error\n");
        fclose(f);
        return 2;
    }
    fclose(f);
    return LLVMFuzzerTestOneInput(data.data(), data.size());
}

